WITH remaining_keys AS (SELECT job_title FROM employees INTERSECT SELECT job_title FROM employees WHERE LOWER(email) LIKE '%enr%'), verified AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.job_title = k.job_title) SELECT s.id, s.full_name, s.email, s.manager_id, s.job_title, s.salary, s.hire_date, s.level, (SELECT MAX(t2.salary) FROM employees t2 WHERE t2.manager_id = s.manager_id) AS max_employee_salary FROM verified s ORDER BY hire_date DESC NULLS FIRST, id DESC
